CREATE EXTENSION IF NOT EXISTS postgis;
CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE profiles(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),auth_subject varchar(255) UNIQUE,display_name varchar(120),email varchar(255),role varchar(32) NOT NULL DEFAULT 'homeowner',preferences jsonb NOT NULL DEFAULT '{}'::jsonb,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE properties(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),owner_profile_id uuid NOT NULL REFERENCES profiles(id) ON DELETE CASCADE,name varchar(160) NOT NULL,property_type varchar(40) NOT NULL DEFAULT 'residential',city varchar(100) NOT NULL DEFAULT 'Hyderabad',state varchar(100) NOT NULL DEFAULT 'Telangana',country_code varchar(3) NOT NULL DEFAULT 'IN',latitude double precision,longitude double precision,location geography(Point,4326),daily_demand_litres numeric(12,2) NOT NULL DEFAULT 540,metadata jsonb NOT NULL DEFAULT '{}'::jsonb,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),CHECK(latitude IS NULL OR latitude BETWEEN -90 AND 90),CHECK(longitude IS NULL OR longitude BETWEEN -180 AND 180));
CREATE INDEX idx_properties_owner ON properties(owner_profile_id);CREATE INDEX idx_properties_location ON properties USING GIST(location);
CREATE TABLE roof_surfaces(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),property_id uuid NOT NULL REFERENCES properties(id) ON DELETE CASCADE,label varchar(120) NOT NULL,area_sq_ft numeric(12,2) NOT NULL CHECK(area_sq_ft>0),runoff_coefficient numeric(5,4) NOT NULL DEFAULT .82 CHECK(runoff_coefficient BETWEEN 0 AND 1),collection_efficiency numeric(5,4) NOT NULL DEFAULT .88 CHECK(collection_efficiency BETWEEN 0 AND 1),roof_material varchar(80) NOT NULL DEFAULT 'concrete',created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE rainfall_observations(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),city varchar(100) NOT NULL,state varchar(100) NOT NULL DEFAULT 'Telangana',year int NOT NULL,month int NOT NULL CHECK(month BETWEEN 1 AND 12),rainfall_mm numeric(8,2) NOT NULL CHECK(rainfall_mm>=0),source varchar(100) NOT NULL DEFAULT 'sample',is_verified boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(city,year,month));
CREATE TABLE water_use_profiles(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),property_id uuid NOT NULL REFERENCES properties(id) ON DELETE CASCADE,occupants int NOT NULL DEFAULT 4 CHECK(occupants>0),bath_events_per_person_day numeric(6,2) NOT NULL DEFAULT 1.2,litres_per_bath_event numeric(8,2) NOT NULL DEFAULT 35,laundry_litres_per_day numeric(8,2) NOT NULL DEFAULT 48,greywater_recovery_fraction numeric(5,4) NOT NULL DEFAULT .65 CHECK(greywater_recovery_fraction BETWEEN 0 AND 1),intended_reuse varchar(80) NOT NULL DEFAULT 'garden_and_flushing',created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE model_versions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name varchar(100) NOT NULL,version varchar(60) NOT NULL,kind varchar(40) NOT NULL DEFAULT 'rule-based',status varchar(30) NOT NULL DEFAULT 'draft',artifact_uri text,metrics jsonb NOT NULL DEFAULT '{}'::jsonb,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(name,version));
CREATE TABLE calculation_runs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),owner_profile_id uuid REFERENCES profiles(id) ON DELETE SET NULL,property_id uuid REFERENCES properties(id) ON DELETE SET NULL,model_version_id uuid REFERENCES model_versions(id) ON DELETE SET NULL,inputs jsonb NOT NULL,outputs jsonb NOT NULL,calculation_version varchar(40) NOT NULL DEFAULT 'engineering-v1',status varchar(30) NOT NULL DEFAULT 'estimate',created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());CREATE INDEX idx_calc_property_created ON calculation_runs(property_id,created_at DESC);
CREATE TABLE recommendations(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),property_id uuid REFERENCES properties(id) ON DELETE SET NULL,calculation_run_id uuid REFERENCES calculation_runs(id) ON DELETE SET NULL,category varchar(40) NOT NULL,title varchar(180) NOT NULL,explanation text NOT NULL,priority varchar(20) NOT NULL DEFAULT 'medium',evidence jsonb NOT NULL DEFAULT '{}'::jsonb,source varchar(30) NOT NULL DEFAULT 'rule-based',created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE sensor_devices(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),property_id uuid NOT NULL REFERENCES properties(id) ON DELETE CASCADE,name varchar(140) NOT NULL,device_type varchar(40) NOT NULL,external_device_id varchar(140) NOT NULL UNIQUE,status varchar(24) NOT NULL DEFAULT 'pending',last_seen_at timestamptz,metadata jsonb NOT NULL DEFAULT '{}'::jsonb,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE sensor_readings(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),device_id uuid NOT NULL REFERENCES sensor_devices(id) ON DELETE CASCADE,observed_at timestamptz NOT NULL,metric varchar(40) NOT NULL,value numeric(14,4) NOT NULL,unit varchar(24) NOT NULL,quality varchar(24) NOT NULL DEFAULT 'valid',payload jsonb NOT NULL DEFAULT '{}'::jsonb,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());CREATE INDEX idx_sensor_readings_device_time ON sensor_readings(device_id,observed_at DESC);
CREATE TABLE treatment_methods(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name varchar(140) NOT NULL UNIQUE,description text NOT NULL,target_use varchar(100) NOT NULL,requires_professional_review boolean NOT NULL DEFAULT true,parameters jsonb NOT NULL DEFAULT '{}'::jsonb,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE water_quality_measurements(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),property_id uuid NOT NULL REFERENCES properties(id) ON DELETE CASCADE,measured_at timestamptz NOT NULL,sample_point varchar(80) NOT NULL,parameter varchar(80) NOT NULL,value numeric(14,4) NOT NULL,unit varchar(24) NOT NULL,lab_name varchar(140),verified boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());CREATE INDEX idx_water_quality_property_time ON water_quality_measurements(property_id,measured_at DESC);
CREATE TABLE prediction_outcomes(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),calculation_run_id uuid NOT NULL REFERENCES calculation_runs(id) ON DELETE CASCADE,observed_at timestamptz NOT NULL,predicted_value numeric(14,4) NOT NULL,observed_value numeric(14,4) NOT NULL,unit varchar(24) NOT NULL,context jsonb NOT NULL DEFAULT '{}'::jsonb,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
